package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.behavior.*; import com.wizzadrds.theworldremembers.equipment.NpcEquipmentManager; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.entity.EquipmentSlot; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.Items;
public final class Phase4BehaviorGameTest { @GameTest public void liveBehaviorAndEquipmentPersist(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);v.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.DIAMOND));c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var state=NpcBehaviorManager.get(c.getLevel().getServer()).get(v.getUUID());var item=NpcEquipmentManager.get(c.getLevel().getServer()).mainHand(v.getUUID());if(state==null){c.fail("No persistent live behavior state");return;}if(!"minecraft:diamond".equals(item)){c.fail("Main-hand equipment was not observed");return;}c.succeed();});}}
